CREATE FUNCTION TD_SYSFNLIB.TD_ORDEREDSTATS()RETURNS TABLE VARYING USING FUNCTION TD_ORDEREDSTATS_CONTRACTLANGUAGE CPPSPECIFIC TD_SYSFNLIB.TD_ORDEREDSTATSNO SQL PARAMETER STYLE TD_INTERNALSQLMR_STYLEFUNCTIONDESCRIPTOR '{
   "functionName" : "TD_ORDEREDSTATS",
   "version" : "1",
   "rewritingRules":
   {
      "iterationFlag":"FALSE",
      "inputType":"fixed",
      "expansionType":"dynamic",
      "instruction":"CASE",
      "numberArguments":"2",
      "argumentsArray":[
      {
         "LogicOperator":"CONDITION",
         "numberArguments":"1",
         "condition": {
            "leftOperand":"$valueFromParameter(PartitionColumns)",
            "operator":"EXISTS",
            "rightOperand":"TRUE"
         },
         "expansionQueryType":"SQLMR_QUERY",
         "expansion":"TD_UNIVSTATSMAP( on (select * from TD_UNPIVOTING(on $Input1 as InputTable partition by ANY USING TARGETCOLUMNS(''$valueFromParameter(TARGETCOLUMNS)'') ATTRIBUTECOLNAME(''Attribute'') VALUECOLNAME(''TD_ATTR_VAL'') ACCUMULATE(''$valueFromParameter(PARTITIONCOLUMNS)'') IncludeNulls(''True'') FunctionName(''TD_UNIVARIATESTATISTICS'') IsDebug(''$valueFromParameter(IsDebug)'') )as UnpivotOut ) as UnivMapIn partition by $RawValueFromParameter(PartitionColumns), Attribute ORDER BY TD_ATTR_VAL using TargetColumns(''TD_ATTR_VAL'') PartitionColumns(''$valueFromParameter(PartitionColumns)'') AttributeColumn(''Attribute'') Stats(''$valueFromParameter(Stats)'') Centiles(''$valueFromParameter(Centiles)'') TrimPercentile(''$valueFromParameter(TrimPercentile)'') ISSPARSEINPUT(''1'') IsDebug(''$valueFromParameter(IsDebug)'') )"
      },
      {
         "LogicOperator":"CONDITION",
         "numberArguments":"1",
         "condition": {
            "leftOperand":"$valueFromParameter(PartitionColumns)",
            "operator":"NOT EXISTS",
            "rightOperand":"TRUE"
         },
         "expansionQueryType":"SQLMR_QUERY",
         "expansion":"TD_UNIVSTATSMAP( on (select * from TD_UNPIVOTING(on $Input1 as InputTable partition by ANY USING TARGETCOLUMNS(''$valueFromParameter(TARGETCOLUMNS)'') ATTRIBUTECOLNAME(''Attribute'') VALUECOLNAME(''TD_ATTR_VAL'') IncludeNulls(''True'') FunctionName(''TD_UNIVARIATESTATISTICS'') IsDebug(''$valueFromParameter(IsDebug)'') )as UnpivotOut ) as UnivMapIn partition by Attribute ORDER BY TD_ATTR_VAL using TargetColumns(''TD_ATTR_VAL'') AttributeColumn(''Attribute'') Stats(''$valueFromParameter(Stats)'') Centiles(''$valueFromParameter(Centiles)'') TrimPercentile(''$valueFromParameter(TrimPercentile)'') ISSPARSEINPUT(''1'') IsDebug(''$valueFromParameter(IsDebug)'') )"
      }
      ]
   }
}' EXTERNAL LOCAL;

