CREATE FUNCTION TD_SYSFNLIB.td_glmpredict()RETURNS TABLE VARYING USING FUNCTION td_glmpredict_contractLANGUAGE CPPSPECIFIC TD_SYSFNLIB.td_glmpredictNO SQLMODE PRIMARYPARAMETER STYLE TD_INTERNALSQLMR_STYLEFUNCTIONDESCRIPTOR '{
  "functionName" : "td_glmpred_internal",
  "version" : "1",
  "I18NCollabSupport" :
       { "InputType": "ALIASED",
         "numberSrcTables" : "2",
         "SourceTableArray" :
          [
             {  "TableName": "$INPUTTABLE",
                "I18NInfo":
                  {
                    "numberParams" : "3",
                    "paramsArray" : ["IDColumn",
                                     "PartitionColumn",
                                     "Accumulate"
                                    ]
                  },
                "CollabInfo":
                  { "isOk2PruneInputs" : "NO",
                    "isRowIndependence" : "NO",
                    "isPartitionIndependence" : "NO"
                  }
             },
             {  "TableName": "$MODELTABLE",
                 "CollabInfo":
                  { "isOk2PruneInputs" : "NO",
                    "isRowIndependence" : "NO",
                    "isPartitionIndependence" : "NO"
                  }
             }
          ]
       },
  "rewritingRules": {
       "iterationFlag": "false",
        "inputType": "aliased",
        "execute_contract": "true",
        "expansionType": "dynamic",
        "instruction": "CASE",
        "numberArguments": "3",
        "argumentsArray": [{
            "LogicOperator": "condition",
            "numberArguments": "1",
            "condition": {
                  "leftOperand": "PartitionBy($INPUTTABLE)",
                  "operator": "NOT EXISTS"
            },
            "expansionQueryType": "SQLMR_QUERY",
            "expansion":
                "td_glmpred_internal(
                    ON $INPUTTABLE as InputTable PARTITION BY ANY
                    ON $MODELTABLE as ModelTable DIMENSION
                    USING
                        IDColumn(''$valueFromParameter(IDColumn)'')
                        Accumulate(''$valueFromParameter(Accumulate)'')
                        OutputProb(''$valueFromParameter(OutputProb)'')
                        Responses(''$valueFromParameter(Responses)'')
                        Family(''$valueFromParameter(Family)'')
                        IsDebug(''$valueFromParameter(IsDebug)'')
                )"
         },{
            "LogicOperator": "AND",
            "numberArguments": "2",
            "conditionArray":
                [
                    {
                        "condition": {
                            "leftOperand": "PartitionBy($INPUTTABLE)",
                            "operator": "EXISTS", "rightOperand":"TRUE"
                        }
                    },
                    {
                        "condition": {
                            "leftOperand": "PartitionBy($MODELTABLE)",
                            "operator": "EXISTS", "rightOperand":"TRUE"
                        }
                    }
                ],
            "expansionQueryType": "SQLMR_QUERY",
            "expansion":
                "td_glmpredictpersegment(
                    ON $INPUTTABLE as InputTable partition by $INPUTTABLE.PartitionBy
                    ON $MODELTABLE as ModelTable partition by $MODELTABLE.PartitionBy
                    USING
                        IDColumn(''$valueFromParameter(IDColumn)'')
                        PartitionColumn(''$valueFromParameter(PartitionColumn)'')
                        Accumulate(''$valueFromParameter(Accumulate)'')
                        OutputProb(''$valueFromParameter(OutputProb)'')
                        Responses(''$valueFromParameter(Responses)'')
                        IsDebug(''$valueFromParameter(IsDebug)'')
                )"
         },
         {
            "LogicOperator": "CONDITION",
            "condition": "DEFAULT",
            "expansionQueryType": "SQLMR_QUERY",
            "expansion":
                "td_glmpredictpersegment(
                    ON $INPUTTABLE as InputTable partition by $INPUTTABLE.PartitionBy $INPUTTABLE.OrderBy
                    ON $MODELTABLE as ModelTable partition by $MODELTABLE.PartitionBy
                    USING
                        IDColumn(''$valueFromParameter(IDColumn)'')
                        PartitionColumn(''$valueFromParameter(PartitionColumn)'')
                        Accumulate(''$valueFromParameter(Accumulate)'')
                        OutputProb(''$valueFromParameter(OutputProb)'')
                        Responses(''$valueFromParameter(Responses)'')
                        IsDebug(''$valueFromParameter(IsDebug)'')
                )"
        }]
    }
}'EXTERNAL LOCAL;

