CREATE FUNCTION TD_SYSFNLIB.TD_TFIDF()RETURNS TABLE VARYING USING FUNCTION TD_TFIDF_CONTRACTSPECIFIC TD_SYSFNLIB.TD_TFIDFLANGUAGE CPPNO SQLDETERMINISTICMODE PRIMARYPARAMETER STYLE TD_INTERNALSQLMR_STYLEFUNCTIONDESCRIPTOR '{
   "functionName": "TD_TFIDF",
   "version": "1",
   "I18NCollabSupport":
   {
      "InputType": "ALIASED",
      "numberSrcTables": "1",
      "SourceTableArray":
      [{
         "TableName": "$InputTable",
         "I18NInfo":
         {
            "numberParams": "3",
            "paramsArray": ["DocIdColumn","TokenColumn","Accumulate"]
         },
         "CollabInfo":
         {
            "isOk2PruneInputs": "NO",
            "isRowIndependence": "NO",
            "isPartitionIndependence": "NO"
         }
      }]
   },
   "rewritingRules":
   {
      "execute_contract": "TRUE",
      "iterationFlag": "FALSE",
      "inputType": "ALIASED",
      "expansionType": "dynamic",
      "instruction": "CASE",
      "numberArguments": "2",
      "argumentsArray":
      [{
         "LogicOperator": "ANDOR",
         "LeftOrChain":
         {
            "numberArguments": "1",
            "conditionArray":
            [{
               "condition":
               {
                  "leftOperand": "$valueFromParameter(Regularization)",
                  "operator": "EXISTS"
               }
            }]
         },
         "RightOrChain":
         {
            "numberArguments": "2",
            "conditionArray":
            [{
               "condition":
               {
                  "leftOperand": "$valueFromParameter(Regularization)",
                  "operator": "=",
                  "rightOperand": "L2",
                  "OperandType": "string"
               }
            },
            {
               "condition":
               {
                  "leftOperand": "$valueFromParameter(Regularization)",
                  "operator": "=",
                  "rightOperand": "L1",
                  "OperandType": "string"
               }
            }]
         },
         "ExpansionQueryType": "SQLMR_QUERY",
         "expansion": "TD_TFIDFREG (
            ON ( SELECT * FROM TD_TFIDFREDUCE (
               ON ( SELECT * FROM TD_TFIDFMAP (
                  ON ( SELECT * FROM $RawValueFromInput($InputTable) inp ) AS InputTable PARTITION BY $RawValueFromParameter(DocIdColumn)
                  USING
                  DocIdColumn (''$ValueFromParameter(DocIdColumn)'')
                  TokenColumn (''$ValueFromParameter(TokenColumn)'')
                  TFNormalization (''$ValueFromParameter(TFNormalization)'')
                  Accumulate (''$ValueFromParameter(Accumulate)'')
                  IsDebug (''$ValueFromParameter(IsDebug)'')
               ) AS dt ) AS TfTable PARTITION BY $RawValueFromParameter(TokenColumn)
               ON ( SELECT COUNT (DISTINCT $RawValueFromParameter(DocIdColumn)) as DocCount FROM $RawValueFromInput($InputTable) dt ) AS DocCountTable DIMENSION
               USING
               DocIdColumn (''$ValueFromParameter(DocIdColumn)'')
               TokenColumn (''$ValueFromParameter(TokenColumn)'')
               IDFNormalization (''$ValueFromParameter(IDFNormalization)'')
               IsDebug (''$ValueFromParameter(IsDebug)'')
            ) AS dt2 ) AS TfIdfTable PARTITION BY $RawValueFromParameter(DocIdColumn)
            USING
            DocIdColumn (''$ValueFromParameter(DocIdColumn)'')
            TokenColumn (''$ValueFromParameter(TokenColumn)'')
            Regularization (''$ValueFromParameter(Regularization)'')
            IsDebug (''$ValueFromParameter(IsDebug)'')
         )"
      },
      {
         "LogicOperator": "CONDITION",
         "condition": "DEFAULT",
         "ExpansionQueryType": "SQLMR_QUERY",
         "expansion": "TD_TFIDFREDUCE (
            ON ( SELECT * FROM TD_TFIDFMAP (
               ON ( SELECT * FROM $RawValueFromInput($InputTable) inp ) AS InputTable PARTITION BY $RawValueFromParameter(DocIdColumn)
               USING
               DocIdColumn (''$ValueFromParameter(DocIdColumn)'')
               TokenColumn (''$ValueFromParameter(TokenColumn)'')
               TFNormalization (''$ValueFromParameter(TFNormalization)'')
               Accumulate (''$ValueFromParameter(Accumulate)'')
               IsDebug (''$ValueFromParameter(IsDebug)'')
            ) AS dt ) AS TfTable PARTITION BY $RawValueFromParameter(TokenColumn)
            ON ( SELECT COUNT (DISTINCT $RawValueFromParameter(DocIdColumn)) as DocCount FROM $RawValueFromInput($InputTable) dt ) AS DocCountTable DIMENSION
            USING
